 */
scwin.ins_search = async function() {
    // var argv = fn_listNewIDChg.arguments;
    // var argc = fn_listNewIDChg.arguments.length;
    // vPAGENO = (argc == 0) ? 0 : vPAGENO = argv[0];

    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
