    url += "&ISU_NM=" + txb_ISU_NM.getValue();
    url += "&SDATE=" + edt_SDATE.getValue();
    url += "&EDATE=" + edt_EDATE.getValue();
    url += "&ACTIV_TP_CD=" + cmb_pACTIV_YN.getValue();
    url += "&CKB_CFI=" + ckb_CFI.getValue();
    url += "&CKB_FISN=" + ckb_FISN.getValue();
    url += "&SCREN_ID=" + "ULDINS21600.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/EtcInfoAction.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*var url = "/listingCommon.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=listGeneralForDynamicName" +
    "&outputMessageId=ULDINS21600_LIST_OUT" +
    "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" +
    "&queryId=lds.ins.etc.select.listCfiValdChk";
    //"&{P}SDATE=" +  edt_SDATE.text +
    //"&{P}EDATE=" +  edt_EDATE.text +
    //"&{P}STD_CD=" +  getObjectValue(txb_STD_CD)  ;

    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    ShowWin(grd_Grid); // 그리드명을 표기*/

};

/**
     * @method
     * @name setBgColorList
     * @description 개선사항 유무에 따른 배경색 설정
     * @returns {void}
     * @hidden N
     */
scwin.setBgColorList = function() {
    // 그리드 컬럼 ID 구하기
    const arrColID = [];
    for (let i = 0; i < grd_Grid.getTotalCol(); i++) {
        arrColID.push(grd_Grid.getColumnID(i));
    }

    // CFI코드 FISN코드 배경색 설정
    for (let j = 0; j < arrColID.length; j++) {
        if (arrColID[j] === 'CFI_CD' || arrColID[j] === 'TO_CFI_CD') {
            $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(CFI_IMPR_REQ_YN,'Y','#FF9900',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
        } else if (arrColID[j] === 'FISN_VAL' || arrColID[j] === 'TO_FISN_VAL') {
            $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(FISN_IMPR_REQ_YN,'Y','#FFFF99',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
        } else {
            $c.cm.setColumnProp(grd_Grid, arrColID[j], 'BgColor', "{decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff')}");
        }
    }
};

/**
 * @method
 * @name ins_all_save
 * @description 일괄저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_all_save = async function() {
    if (js_svrGubun === 'dr') {
        await $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        return;
    }
    if (scwin.chkValid() === false) {
        await $c.win.alert("CFI정합성 적용대상을 선택하세요.");
        return;
    }
    if (scwin.chkValidSixLength() === false) {
        await $c.win.alert("6자리가 아닌 CFI코드가 존재합니다.");
        return;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }
    trs_autosave.KeyName = "toinb_dataid4";
    // [전환검토] trs_autosave.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     EMP_NO : js_emp_no,
    //     EMP_NM : js_emp_nm,
    //     EMAIL : js_email
    // };
    const sbmOptions = {
        id : "sbm_trs_autosave",
        action : "/EtcInfoAction.do",
        ref : "dts_Rst,dts_List",
        target : "trs_autosave=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name chkValid
 * @description 일괄저장 체크대상을 알아낸다.
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    let cnt = 0;
    for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") === "T") {
            cnt++;
        }
    }
    // alert("cnt " +cnt);
    if (Number(cnt) > 0) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name chkValidSixLength
 * @description 일괄저장시 CFI 6자리 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValidSixLength = function() {
    let cnt = 0;
    for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
        // alert(dts_List.NameString(nRow, "TO_CFI_CD").replace("_","").length);
        if (dts_List.getCellData(nRow, "CHK") === "T") {
            if (dts_List.getCellData(nRow, "TO_CFI_CD").replace("_", "").length < 6) {
                cnt++;
            }
        }
    }
    // alert("cnt " +cnt);
    if (Number(cnt) > 0) {
        return false;
    } else {
        return true;
    }
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달값을 설정한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name selectAll
 * @description 체크박스 전체선택
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    grd_Grid.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭한것

        scwin.gAllChk = true;
        dts_List.setBroadcast(false);
        for (let i = 0; i < dts_List.getRowCount(); i++) {
            // if (dts_List.NameString(i + 1, "TO_CFI_LEN") == '6') { //수익처리대상여부
            //    dts_List.NameString(i + 1, "CHK") = "T";
            // } else {
            //    dts_List.NameString(i + 1, "CHK") = "F";
            // }
            dts_List.setCellData(i + 1, "CHK", "T");
        }
        dts_List.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dts_List.setBroadcast(false);
        for (let i = 0; i < dts_List.getRowCount(); i++) {
            dts_List.setCellData(i + 1, "CHK", "F");
        }
        dts_List.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Grid.Redraw = true;
};

/**
